[
  {
    "statement": "Studies in the North Sea have found various gear modifications to be effective in reducing the unwanted catch of cod and haddock.",
    "citations": []
  },
  {
    "statement": "A separator trawl with a larger mesh size in the lower codend allowed more unwanted smaller cod to escape.",
    "citations": [
      "2711"
    ]
  },
  {
    "statement": "Topless trawls have been found to reduce the catch of unwanted Atlantic cod.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "One study found that topless trawls reduced unwanted catches of larger haddock and larger Atlantic cod.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "One study found that topless trawls did not reduce unwanted catches of smaller haddock.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Fitting size-sorting escape grids to trawl nets has been shown to reduce the catch of unwanted sizes of cod and haddock.",
    "citations": []
  },
  {
    "statement": "One study found that size-sorting escape grids improved the size-selection of haddock, but not cod, compared to standard nets.",
    "citations": [
      "2720"
    ]
  },
  {
    "statement": "Another study found that trawl nets with an escape grid did not improve the size-selection of cod and haddock when compared to nets with square mesh escape windows.",
    "citations": [
      "2720"
    ]
  }
]

[
  {
    "statement": "A study in the English Channel found that the size-selectivity of whiting was increased in bottom trawl nets fitted with square mesh escape panels or cylinders in combination with one or two size-sorting grids of different types, compared to standard nets.",
    "citations": [
      "2727"
    ]
  },
  {
    "statement": "Four of five replicated studies found that bottom trawl nets fitted with square mesh escape panels and size-sorting grids of various types reduced the unwanted catch of fish, sharks, stingrays, rays, and total discarded catch, compared to standard unmodified trawl nets.",
    "citations": [
      "2727"
    ]
  },
  {
    "statement": "The escape of non-target fish from the combined use of a square mesh panel and a grid depended on the position of the panel in the net.",
    "citations": [
      "2727"
    ]
  },
  {
    "statement": "Three of four replicated studies found that trawl nets fitted with both a size-sorting escape grid and a large supported escape opening reduced the catches of unwanted fish, sharks, and rays, compared to standard trawl nets.",
    "citations": [
      "2726"
    ]
  },
  {
    "statement": "Trawl nets fitted with both a size-sorting escape grid and a large supported escape opening did not reduce the catches of sawfish in three of four replicated studies.",
    "citations": [
      "2726"
    ]
  },
  {
    "statement": "One study found that trawl nets with an escape grid and opening caught similar amounts of unwanted sharks as trawl nets without these modifications.",
    "citations": [
      "2276"
    ]
  }
]

[
  {
    "statement": "A study in the Coral Sea found that in areas closed to non-towed fishing gears, overall shark abundance was higher when sampled with longlines but not gillnets, compared to areas where commercial gillnets were permitted.",
    "citations": [
      "2670"
    ]
  },
  {
    "statement": "A study in the Indian Ocean found that prohibiting offshore line fishing and all other boat-based fishing in a marine protected area zone resulted in higher abundances of four over-exploited fish species compared to zones where boat-based line and spear fishing was permitted.",
    "citations": [
      "2671"
    ]
  },
  {
    "statement": "One study in the Greenland Sea, North Pacific Ocean and the North Atlantic Ocean found that an area where fishing gears targeting bottom-dwelling species had been prohibited for 15 years had higher numbers of cod than openly fished areas.",
    "citations": [
      "2654"
    ]
  },
  {
    "statement": "A study found that fish densities in areas closed to mobile and static bottom fish gears for at least 11 years varied between fish species and groups, and also with depth and temperature.",
    "citations": [
      "2654"
    ]
  },
  {
    "statement": "A study found that prohibiting mobile and static bottom fish gears in protected areas for 2–7 years had no effect on fish densities compared to non-protected areas.",
    "citations": [
      "2654"
    ]
  }
]

[
