    ]
  },
  {
    "statement": "Fish had larger average sizes in zones where fishing was prohibited or nearly all prohibited, compared to zones with fewer fishing restrictions.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "A study noted different age and sex structures for the fish species steentjies between a no-fishing zone, a fished multipurpose zone, and an unprotected fished site.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "Blackspot snapper were found to be larger inside a marine park with unspecified fishing restrictions compared to more intensely fished areas outside the park.",
    "citations": [
      "2680"
    ]
  },
  {
    "statement": "Blackspot snapper were found to be older inside a marine park with unspecified fishing restrictions compared to more intensely fished areas outside the park.",
    "citations": [
      "2680"
    ]
  },
  {
    "statement": "A global review reported that five of 11 studies found fish were larger inside reserves with restricted fishing.",
    "citations": [
      "2680"
    ]
  },
  {
    "statement": "The survival rate for blackspot snapper was higher within a marine park with unspecified fishing restrictions compared to more heavily fished areas outside the park.",
    "citations": [
      "2680"
    ]
  },
  {
    "statement": "Tagged reef fish were mostly recaptured within the zones where fishing was prohibited.",
