    "citations": [
      "2711"
    ]
  },
  {
    "statement": "Two of four studies found that using a topless trawl reduced the catch of unwanted Atlantic cod.",
    "citations": [
      "2712"
    ]
  },
  {
    "statement": "Two of four studies found that using a topless trawl reduced discards of commercial fish species.",
    "citations": [
