[
  {
    "statement": "Modifying fishing trap or pot configurations has been shown to have several effects on marine fish.",
    "citations": []
  },
  {
    "statement": "Sixteen of twenty studies found that modifications such as using a different trap type, increasing mesh size, or fitting an escape device reduced the unwanted catches of fish.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "The reduced unwanted catches of fish included undersized, discarded, or non-commercial target species like brown trout, black sea bass, herring, and cod.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "One study found that the number of unwanted species, including fish and invertebrates, was lower in modified traps.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Three other studies found that trap modifications had no effect on the unwanted catches of white croaker, non-commercial fish, or undersized Atlantic cod.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "In one case, non-target haddock catches were increased by trap modifications.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Three of four studies found that traps modified with a square mesh escape window or larger mesh sizes improved the size-selectivity of Atlantic cod, black sea bass, and most fish species.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Another study found that increasing the mesh size of a trap escape panel had no effect on the size-selectivity of panga.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "One study on survival rates found that the survival of small herring that escaped from a pontoon fish trap through a size-sorting grid was similar to the survival of trap-caught herring that did not pass through a grid.",
    "citations": [
      "2702"
    ]
  },
  {
    "statement": "Modifications to fishing nets to prevent seal access, such as installing wire grids or steel bars, have been found to reduce damage to salmon catches by seals.",
    "citations": [
      "2822"
    ]
  },
  {
    "statement": "Modifications to fishing nets to prevent seal access have resulted in higher catches of undamaged salmon.",
    "citations": [
      "2822"
    ]
  }
]

[
  {
    "statement": "Nine studies have examined the effectiveness of attaching electropositive deterrents to fishing gear.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "Studies on the effectiveness of attaching electropositive deterrents to fishing gear were conducted in the Atlantic Ocean, the Gulf of Alaska, the South Pacific Ocean, the Tasman Sea, and in laboratory settings.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "Three out of four replicated studies found that the presence of deterrent materials near bait reduced the frequency of feeding attempts by spiny dogfish, great hammerhead, and draughtboard sharks.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "Three out of four replicated studies found that the presence of deterrent materials near bait reduced bait consumption by spiny dogfish, great hammerhead, and draughtboard sharks.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "One study found that a deterrent material did not reduce bait consumption by bonnethead and young lemon sharks.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "One study on deterrent materials found that the bait consumption of commercially valuable Pacific halibut was unaffected by the deterrent materials.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "Two of four replicated, controlled studies found that fishing gear equipped with electropositive deterrents caught fewer unwanted spiny dogfish, longnose skate, sharks, and rays compared to standard fishing gear.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "Two of four replicated, controlled studies found that fishing gear equipped with electropositive deterrents caught fewer undersized halibut compared to standard fishing gear.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "Two replicated, controlled studies found that electropositive deterrents on fishing gear resulted in similar catches of unwanted spiny dogfish, sharks, and rays when compared to gear without deterrents.",
    "citations": [
      "2696"
    ]
  },
  {
    "statement": "A global systematic review found that electropositive deterrents on fishing gear resulted in similar catches of unwanted spiny dogfish, sharks, and rays when compared to gear without deterrents.",
    "citations": [
      "2696"
    ]
  }
]

[
  {
    "statement": "Evidence from European waters on the effectiveness of using a square mesh codend instead of a diamond mesh codend for reducing unwanted catch shows varied results.",
    "citations": []
  },
  {
    "statement": "A review of 26 studies, many conducted in European waters, found that 10 of 16 studies reported that square mesh codends reduced unwanted or non-marketable catches of various fish species when compared to diamond mesh codends.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "Four of the reviewed studies found no reduction in unwanted catches for certain species when using square mesh codends.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "Another study found that unwanted catch was dependent on mesh size as well as mesh shape.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "Six of 14 studies on size selectivity found that square mesh codends improved size selectivity for several fish species.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "Five of 14 studies on size selectivity found no difference between square and diamond mesh codends.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "The effect of the mesh shape on size selectivity could vary depending on the fish's body shape.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "There is evidence that the short-term survival of some fish species is higher after escaping through a square mesh codend.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "One study in the English Channel discovered that a trawl net with a square mesh codend and square mesh escape panels was effective in reducing the amount of discarded finfish in comparison to a diamond mesh codend without panels.",
    "citations": [
      "2724"
    ]
  },
  {
    "statement": "Another study in the English Channel found that a trawl with a square mesh codend caught fewer non-commercial unwanted invertebrates in one of two areas studied when compared to a diamond mesh codend.",
    "citations": [
      "2136"
    ]
  }
]

[
  {
    "statement": "Ceasing or prohibiting all fishing in a marine protected area has shown varied effects on fish community composition and species richness.",
    "citations": []
  },
  {
    "statement": "A study in the Caribbean Sea indicated that after seven years, protected areas closed to all fishing exhibited lower total fish species richness compared to unprotected areas.",
    "citations": [
      "2681"
    ]
  },
  {
    "statement": "A study from the Philippine Sea found a higher number of fish species in the no-fishing zone of a multi-zoned protected area after 10 to 15 years, when compared with partially fished and unprotected areas.",
    "citations": [
      "2674"
    ]
  },
  {
    "statement": "A study in the Skagerrak found that cod survival increased within a marine protected area eight years after fishing was prohibited, compared to fished areas outside the reserve.",
    "citations": [
      "2681"
    ]
  }
]

[
  {
    "statement": "Rotating a diamond mesh codend by 90° improved size selection for cod, red mullet, common pandora, and other round-bodied fish species.",
    "citations": [
      "2715"
    ]
  },
  {
    "statement": "Rotating a diamond mesh codend by 90° did not improve size selection for plaice, annular sea bream, and other flatfish species.",
    "citations": [
      "2715"
    ]
  },
  {
    "statement": "One study found that a rotated diamond mesh did not improve size selectivity for cod, plaice, or flounder.",
    "citations": [
      "2715"
    ]
  },
  {
    "statement": "A square mesh codend improved size selectivity for silver hake, horse mackerel, European hake, axillary seabream, poor cod, greater forkbeard, and blue whiting.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "A square mesh codend improved size selectivity for three out of four commercially targeted fish.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "Some studies found no difference in size selectivity between square and diamond mesh codends for Atlantic mackerel, long rough dab, yellowtail scad, striped seapike, rockfish, and flatfish.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "The effectiveness of square mesh codends varied by fish body shape.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "Square mesh codends showed improved selectivity for roundfish.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "Square mesh codends did not show improved selectivity for flatfish.",
    "citations": [
      "2714"
    ]
  },
  {
    "statement": "An increase in mesh size can increase size selectivity for both square and diamond mesh codends.",
    "citations": [
      "2714"
    ]
  }
]

[
  {
    "statement": "In the Tasman Sea, a before-and-after study found that the fish assemblage and species composition were different after prohibiting all commercial fishing in an estuary for two years.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the South Atlantic Ocean, a site comparison study found no change in species composition between a reserve closed to all commercial fishing for 40 years and unprotected fished areas.",
    "citations": [
      "2667"
    ]
  }
]

[
  {
    "statement": "After one to eight years of prohibiting all fishing with limited exceptions, the abundance of copper rockfish, quillback rockfish, china rockfish and lingcod was similar to sites open to fishing.",
    "citations": [
      "2681"
    ]
  },
  {
    "statement": "After seven years of restricting all fishing except for bait fishing, there was similar total fish biomass compared to unprotected areas.",
    "citations": [
      "2681"
    ]
  },
  {
    "statement": "After seven years of restricting all fishing except for bait fishing, there was lower total fish density compared to unprotected areas.",
    "citations": [
      "2681"
    ]
  },
  {
    "statement": "Cod survival increased inside a marine protected area in the eight years after almost all fishing was prohibited, compared to fished areas.",
    "citations": [
      "2681"
    ]
